def bits(v, w):
    return '"' + format(v & ((1 << w) - 1), "0" + str(w) + "b") + '"'


def arr(name, typ, vals, w):
    rows = []
    for i in range(0, len(vals), 16):
        rows.append("        " + ", ".join(bits(v, w) for v in vals[i:i + 16]))
    return "    constant " + name + " : " + typ + " := (\n" + ",\n".join(rows) + "\n    );"


def emit():
    code = [int(c, 16) for c in SCENE]           # row-major, 128 x 96
    busy = [int(c) for c in BUSY]                # row-major, 32 x 48
    cs = []
    for rp in (0, 1):
        for cp in (0, 1):
            for blk in range(3):
                vals = []
                for cb4 in range(16):
                    for rb in range(64):
                        cb = blk * 16 + cb4
                        vals.append(code[(2 * rb + rp) * 96 + 2 * cb + cp])
                cs.append(arr("C_SC%d%d%d" % (rp, cp, blk), "t_sc", vals, 4))
    bz = [0] * 2048
    for r in range(32):
        for c in range(48):
            bz[r * 48 + c] = busy[r * 48 + c]
    cs.append(arr("C_BUSY", "t_busy", bz, 2))
    cs.append(arr("C_PYU", "t_pyu", [(p[0] << 8) | p[1] for p in PAL], 16))
    cs.append(arr("C_PV", "t_pv", [p[2] for p in PAL], 8))
    cs.append(arr("C_LEV", "t_lev", LEV + [0], 8))
    txt = ("-- idol_pkg.vhd -- GENERATED by idol.py; edit the generator, not this file.\n\n"
           "library ieee;\nuse ieee.std_logic_1164.all;\n\npackage idol_pkg is\n"
           "    type t_sc is array(0 to 1023) of std_logic_vector(3 downto 0);\n"
           "    type t_busy is array(0 to 2047) of std_logic_vector(1 downto 0);\n"
           "    type t_pyu is array(0 to 255) of std_logic_vector(15 downto 0);\n"
           "    type t_pv is array(0 to 255) of std_logic_vector(7 downto 0);\n"
           "    type t_lev is array(0 to 15) of std_logic_vector(7 downto 0);\n"
           "    constant C_YEL_Y : integer := %d;\n    constant C_YEL_U : integer := %d;\n"
           "    constant C_YEL_V : integer := %d;\n" % tuple(YEL) +
           "\n".join(cs) + "\nend package idol_pkg;\n")
    with open(os.path.join(HERE, "idol_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
